from math import exp
from typing import Sequence

def softmax(z: Sequence[float]) -> list[float]:
    m=max(z); e=[exp(x-m) for x in z]; s=sum(e)
    return [x/s for x in e]

def run() -> None:
    z=[0.2,-0.4,0.7]; q=[1.5,-0.5,2.0]; j=0
    p=softmax(z); psi=[float(a==j)-p[j] for a in range(len(p))]
    for b in [0.0,1.0,10.0]:
        g=sum(pa*sa*(qa-b) for pa,sa,qa in zip(p,psi,q))
        print(f"baseline={b:4.1f}, gradient={g:.10f}")
    print("mean score:",sum(pa*sa for pa,sa in zip(p,psi)))
if __name__ == "__main__": run()

from typing import Sequence

def audit(b: Sequence[float], t: Sequence[float], g: Sequence[float], eps: float) -> tuple[float,float]:
    if eps<=0 or any(x<=0 for x in b) or any(x<eps*y for x,y in zip(b,t)): raise ValueError("coverage failed")
    moment=sum(x*((y/x)*z)**2 for x,y,z in zip(b,t,g))
    bound=sum(y*z*z for y,z in zip(t,g))/eps
    return moment,bound
if __name__ == "__main__":
    for eps in [.5,.2,.1,.05]:
        m,B=audit([eps,1-eps],[1.,0.],[1.,0.],eps)
        print(f"epsilon={eps:.2f}: moment={m:.2f}, bound={B:.2f}")

