from typing import Sequence

def exact_policy_gradient(p: Sequence[float], score: Sequence[Sequence[float]], q: Sequence[float], baseline: float=0.0) -> list[float]:
    if not (len(p)==len(score)==len(q)): raise ValueError("length mismatch")
    d=len(score[0])
    return [sum(p[a]*score[a][j]*(q[a]-baseline) for a in range(len(p))) for j in range(d)]

from dataclasses import dataclass
from typing import Sequence
@dataclass(frozen=True)
class Audit: moment: float; bound: float; ratio: float
def coverage_audit(b: Sequence[float],t: Sequence[float],g: Sequence[float],eps: float)->Audit:
    if eps<=0 or any(x<=0 for x in b) or any(x<eps*y for x,y in zip(b,t)): raise ValueError("invalid coverage")
    m=sum(x*(y/x*z)**2 for x,y,z in zip(b,t,g)); B=sum(y*z*z for y,z in zip(t,g))/eps
    return Audit(m,B,m/B if B else 0.0)

